def list_issues(issues, status=None, page=1, page_size=2):
    if type(page) is not int or type(page_size) is not int or page < 1 or page_size < 1:
        raise ValueError('page and page_size must be positive integers')
    matching = [item for item in issues if status is None or item['status'] == status]
    start = (page - 1) * page_size
    return matching[start:start + page_size]

