updates.good_source:
def update_issue(issues, issue_id, changes):
    if type(issue_id) is not int or issue_id <= 0:
        raise ValueError('issue_id must be a positive integer')
    if not isinstance(changes, dict) or any(key not in ('title', 'status') for key in changes):
        raise ValueError('invalid patch')
    if 'title' in changes and (not isinstance(changes['title'], str) or not changes['title'].strip()):
        raise ValueError('invalid title')
    if 'status' in changes and changes['status'] not in ('open', 'closed'):
        raise ValueError('invalid status')
    if not any(issue['id'] == issue_id for issue in issues):
        raise ValueError('unknown issue')
    result = [dict(issue) for issue in issues]
    for issue in result:
        if issue['id'] == issue_id:
            issue.update(changes)
    return result

