import unittest
from copy import deepcopy
from issues import update_issue

class UpdateTests(unittest.TestCase):
    def setUp(self):
        self.rows = [{'id': 2, 'title': 'Two', 'status': 'closed'}, {'id': 1, 'title': 'One', 'status': 'open'}]
    def test_patch_without_mutation(self):
        original = deepcopy(self.rows)
        patch = {'title': ' New ', 'status': 'closed'}
        result = update_issue(self.rows, 1, patch)
        self.assertEqual(result, [self.rows[0], {'id': 1, 'title': ' New ', 'status': 'closed'}])
        self.assertEqual(self.rows, original)
        self.assertEqual(patch, {'title': ' New ', 'status': 'closed'})
        self.assertEqual(update_issue(self.rows, 2, {}), self.rows)
    def test_invalid_ids(self):
        for identifier in (True, 0, -1, '1', 1.0, 99):
            with self.subTest(identifier=identifier):
                with self.assertRaises(ValueError):
                    update_issue(self.rows, identifier, {})
    def test_invalid_patches_are_atomic(self):
        original = deepcopy(self.rows)
        for patch in (None, [], {'id': 4}, {'extra': 1}, {'title': ''}, {'title': ' '}, {'title': 7}, {'status': None}, {'title': 'Valid', 'status': 'pending'}):
            with self.subTest(patch=patch):
                with self.assertRaises(ValueError):
                    update_issue(self.rows, 1, patch)
                self.assertEqual(self.rows, original)

